import { join } from "node:path";
import type * as Engine from "./engine";

let engine: typeof Engine | undefined;

/**
 * Loads the built-in engine (generated by scripts/prebuild.mjs) on first use. It's large and most
 * Yaak sessions never build docs, so it isn't part of the plugin bundle: `yaak.buildAssets` in
 * package.json ships it next to `build/index.js`.
 */
export function loadEngine(): typeof Engine {
  engine ??= require(join(__dirname, "engine.cjs")) as typeof Engine;
  return engine;
}
